// ServerInterface represents all server handlers.
type ServerInterface interface {
	// List assets (paginated)
	// (GET /assets)
	ListAssets(w http.ResponseWriter, r *http.Request, params ListAssetsParams)
	// Create an asset entity
	// (POST /assets)
	CreateAsset(w http.ResponseWriter, r *http.Request)
	// Soft-delete an asset
	// (DELETE /assets/{id})
	DeleteAsset(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)

	// (GET /assets/{id})
	GetAsset(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)

	// (PATCH /assets/{id})
	UpdateAsset(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// All field values for an asset
	// (GET /assets/{id}/fields)
	GetAssetFields(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Clear a field value
	// (DELETE /assets/{id}/fields/{field_id})
	ClearAssetFieldValue(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, fieldId openapi_types.UUID)
	// Set or replace a single field value
	// (PUT /assets/{id}/fields/{field_id})
	SetAssetFieldValue(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, fieldId openapi_types.UUID)
	// Audit trail of changes to one field on one asset
	// (GET /assets/{id}/fields/{field_id}/history)
	GetAssetFieldValueHistory(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, fieldId openapi_types.UUID, params GetAssetFieldValueHistoryParams)
	// Download the asset's primary file (original variant)
	// (GET /assets/{id}/file)
	DownloadAssetFile(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, params DownloadAssetFileParams)
	// Add tags to an asset (bulk, idempotent)
	// (POST /assets/{id}/tags)
	AddAssetTags(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)

	// (DELETE /assets/{id}/tags/{tag})
	RemoveAssetTag(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, tag string)
	// Download a named variant of the asset (thumb / preview / etc.)
	// (GET /assets/{id}/variants/{variant})
	DownloadAssetVariant(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, variant string, params DownloadAssetVariantParams)
	// List every capability the server knows about
	// (GET /auth/capabilities)
	ListCapabilities(w http.ResponseWriter, r *http.Request)
	// Sign in with username and password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// End the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Return information about the caller
	// (GET /auth/me)
	GetCurrentUser(w http.ResponseWriter, r *http.Request)
	// Effective capabilities for the current user
	// (GET /auth/me/capabilities)
	GetMyCapabilities(w http.ResponseWriter, r *http.Request)
	// Teams the caller is a member of (direct memberships)
	// (GET /auth/me/teams)
	GetMyTeams(w http.ResponseWriter, r *http.Request)
	// List roles and the capabilities attached to each
	// (GET /auth/roles)
	ListRoles(w http.ResponseWriter, r *http.Request)
	// List the caller's API tokens
	// (GET /auth/tokens)
	ListApiTokens(w http.ResponseWriter, r *http.Request)
	// Issue a new API token
	// (POST /auth/tokens)
	CreateApiToken(w http.ResponseWriter, r *http.Request)
	// Revoke an API token by ID
	// (DELETE /auth/tokens/{id})
	RevokeApiToken(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Assign a role to a user (admin)
	// (PUT /auth/users/{ref}/role)
	SetUserRole(w http.ResponseWriter, r *http.Request, ref int64)
	// List collections (filterable, paginated)
	// (GET /collections)
	ListCollections(w http.ResponseWriter, r *http.Request, params ListCollectionsParams)
	// Create a new collection
	// (POST /collections)
	CreateCollection(w http.ResponseWriter, r *http.Request)
	// Hard-delete a collection
	// (DELETE /collections/{id})
	DeleteCollection(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Fetch a single collection by id
	// (GET /collections/{id})
	GetCollection(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Partial update of a collection
	// (PATCH /collections/{id})
	UpdateCollection(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List ACL entries on a collection
	// (GET /collections/{id}/acls)
	ListCollectionAcls(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Grant a permission on a collection to a principal
	// (POST /collections/{id}/acls)
	AddCollectionAcl(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Revoke a specific permission row from a principal
	// (DELETE /collections/{id}/acls/{principal_type}/{principal_id}/{permission})
	RemoveCollectionAcl(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, principalType string, principalId string, permission string)
	// List the assets pinned in a collection
	// (GET /collections/{id}/resources)
	ListCollectionResources(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, params ListCollectionResourcesParams)
	// Add (or re-pin) an asset in a collection
	// (POST /collections/{id}/resources)
	AddCollectionResource(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Remove an asset from a collection
	// (DELETE /collections/{id}/resources/{asset_id})
	RemoveCollectionResource(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, assetId openapi_types.UUID)
	// Soft-delete a comment
	// (DELETE /comments/{id})
	DeleteComment(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List field definitions (the metadata schema)
	// (GET /fields)
	ListFields(w http.ResponseWriter, r *http.Request, params ListFieldsParams)
	// Create a new field definition (admin)
	// (POST /fields)
	CreateField(w http.ResponseWriter, r *http.Request)
	// Archive (soft-delete) a field definition (admin)
	// (DELETE /fields/{id})
	ArchiveField(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)

	// (GET /fields/{id})
	GetField(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Update a field definition (admin)
	// (PATCH /fields/{id})
	UpdateField(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List posts (paginated feed)
	// (GET /posts)
	ListPosts(w http.ResponseWriter, r *http.Request, params ListPostsParams)
	// Publish a new post
	// (POST /posts)
	CreatePost(w http.ResponseWriter, r *http.Request)
	// Soft-delete a post
	// (DELETE /posts/{id})
	DeletePost(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Fetch a post with its members + tags
	// (GET /posts/{id})
	GetPost(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Partial update of a post
	// (PATCH /posts/{id})
	UpdatePost(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List ACL entries on a post
	// (GET /posts/{id}/acls)
	ListPostAcls(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Grant a permission on a post to a principal
	// (POST /posts/{id}/acls)
	AddPostAcl(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Revoke a specific permission row from a principal
	// (DELETE /posts/{id}/acls/{principal_type}/{principal_id}/{permission})
	RemovePostAcl(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, principalType string, principalId string, permission string)
	// Attach an existing asset to a post
	// (POST /posts/{id}/assets)
	AddPostAsset(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Remove an asset from a post
	// (DELETE /posts/{id}/assets/{asset_id})
	RemovePostAsset(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, assetId openapi_types.UUID)
	// List the comment thread on a post
	// (GET /posts/{id}/comments)
	ListPostComments(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, params ListPostCommentsParams)
	// Post a comment (or reply) on a post
	// (POST /posts/{id}/comments)
	CreatePostComment(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Remove the caller's like on a post
	// (DELETE /posts/{id}/like)
	UnlikePost(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Whether the current caller has liked this post
	// (GET /posts/{id}/like)
	GetPostLike(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Like a post
	// (POST /posts/{id}/like)
	LikePost(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List all resource types
	// (GET /resource_types)
	ListResourceTypes(w http.ResponseWriter, r *http.Request)
	// Finalize first-run setup (admin + site + SMTP)
	// (POST /setup/complete)
	CompleteSetup(w http.ResponseWriter, r *http.Request)
	// First-run setup status + admin-form prefills
	// (GET /setup/status)
	GetSetupStatus(w http.ResponseWriter, r *http.Request)
	// Upload a raw byte stream
	// (POST /storage/objects)
	UploadStorageObject(w http.ResponseWriter, r *http.Request, params UploadStorageObjectParams)
	// Download a raw byte stream by content hash (original variant)
	// (GET /storage/objects/{hash})
	DownloadStorageObject(w http.ResponseWriter, r *http.Request, hash string, params DownloadStorageObjectParams)
	// Download a specific variant of a stored object
	// (GET /storage/objects/{hash}/variants/{variant})
	DownloadStorageObjectVariant(w http.ResponseWriter, r *http.Request, hash string, variant string, params DownloadStorageObjectVariantParams)
	// List teams (paginated; optional ancestor filter)
	// (GET /teams)
	ListTeams(w http.ResponseWriter, r *http.Request, params ListTeamsParams)
	// Create a team
	// (POST /teams)
	CreateTeam(w http.ResponseWriter, r *http.Request)
	// Soft-delete a team
	// (DELETE /teams/{id})
	DeleteTeam(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Fetch a team with its direct parents
	// (GET /teams/{id})
	GetTeam(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Rename or re-describe a team
	// (PATCH /teams/{id})
	UpdateTeam(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List a team's members
	// (GET /teams/{id}/members)
	ListTeamMembers(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Add a user to a team
	// (POST /teams/{id}/members)
	AddTeamMember(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Remove a user from a team
	// (DELETE /teams/{id}/members/{rs_user_id})
	RemoveTeamMember(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, rsUserId int64)
	// List the team's direct parents
	// (GET /teams/{id}/parents)
	ListTeamParents(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Add a parent edge (creates a DAG link)
	// (POST /teams/{id}/parents)
	AddTeamParent(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Sever a parent edge
	// (DELETE /teams/{id}/parents/{parent_id})
	RemoveTeamParent(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, parentId openapi_types.UUID)
	// Public profile by username (used by /@username URLs)
	// (GET /users/by-username/{username})
	GetUserPublicByUsername(w http.ResponseWriter, r *http.Request, username string)
	// Public profile for a user (by RS ref)
	// (GET /users/{ref})
	GetUserPublicByRef(w http.ResponseWriter, r *http.Request, ref int64)
	// Edit a user's profile (self or moderator)
	// (PATCH /users/{ref})
	UpdateUserProfile(w http.ResponseWriter, r *http.Request, ref int64)
}

